function perfectpixel_quote_is_checkout_page() {
	// Not on the "pay for order" page: there the customer pays the revised order normally.
	return function_exists( 'is_checkout' ) && is_checkout() && ! is_wc_endpoint_url( 'order-pay' );
}

function perfectpixel_quote_only_cheque( $gateways ) {
	if ( is_admin() || ! perfectpixel_quote_is_checkout_page() || ! isset( $gateways['cheque'] ) ) {
		return $gateways;
	}
	return array( 'cheque' => $gateways['cheque'] );
}

function perfectpixel_quote_button_text( $text ) {
	return perfectpixel_quote_is_checkout_page() ? '{{quote_button_text}}' : $text;
}

function perfectpixel_quote_gateway_title( $title, $gateway_id ) {
	return 'cheque' === $gateway_id && perfectpixel_quote_is_checkout_page() ? '{{quote_gateway_title}}' : $title;
}
